Date: Tue, 24 Nov 2026 20:08:28 +0100
Subject: [PATCH] daemon: Show the greeter after resume when the user's home is
 locked

With systemd-homed's suspend option the home is locked during sleep and
the session stays frozen, so nothing could ask for the password again.
On resume, show the greeter: logging in there unlocks home and session.

BUG: 488104
---
 src/daemon/SeatManager.cpp | 44 ++++++++++++++++++++++++++++++++++++--
 src/daemon/SeatManager.h   |  1 +
 2 files changed, 43 insertions(+), 2 deletions(-)

diff --git a/src/daemon/SeatManager.cpp b/src/daemon/SeatManager.cpp
index 45daa008..b2656883 100644
--- a/src/daemon/SeatManager.cpp
+++ b/src/daemon/SeatManager.cpp
@@ -79,6 +79,10 @@ public:
     {
         return m_isGreeter;
     }
+    [[nodiscard]] QString userName() const
+    {
+        return m_userName;
+    }

     [[nodiscard]] static bool isGreeter(const OrgFreedesktopLogin1SessionInterface &sessionInterface)
     {
@@ -95,6 +99,7 @@ private:
     QString m_seatName;
     uint m_vtNr = 0;
     QString m_id;
+    QString m_userName;
     QDBusObjectPath m_objectPath;
     bool m_isGreeter = false;
 };
@@ -202,9 +207,9 @@ LogindSession::LogindSession(const QDBusObjectPath &objectPath, const QString &s
     m_id = session.id();
     m_vtNr = session.vTNr();

-    auto userName = session.name(); // the Name property is indeed the user's name
+    m_userName = session.name(); // the Name property is indeed the user's name
     auto service = session.service();
-    m_isGreeter = (userName == "plasmalogin"_L1 && service == "plasmalogin-greeter"_L1);
+    m_isGreeter = (m_userName == "plasmalogin"_L1 && service == "plasmalogin-greeter"_L1);
 }

 QString LogindSession::seatName() const
@@ -251,6 +256,7 @@ void SeatManager::initialize()
     connect(m_logind, &OrgFreedesktopLogin1ManagerInterface::SessionNew, this, &SeatManager::logindSessionAdded);
     connect(m_logind, &OrgFreedesktopLogin1ManagerInterface::SessionRemoved, this, &SeatManager::logindSessionRemoved);
     connect(m_logind, &OrgFreedesktopLogin1ManagerInterface::SecureAttentionKey, this, &SeatManager::logindSecureAttentionKey);
+    connect(m_logind, &OrgFreedesktopLogin1ManagerInterface::PrepareForSleep, this, &SeatManager::logindPrepareForSleep);
 }

 void SeatManager::createSeat(const QString &name)
@@ -311,6 +317,40 @@ void SeatManager::logindSecureAttentionKey(const QString &name, [[maybe_unused]]
     daemonApp->seatManager()->switchToGreeter(name);
 }

+void SeatManager::logindPrepareForSleep(bool start)
+{
+    if (start) {
+        return;
+    }
+
+    // systemd-homed may lock home directories during suspend, which also freezes the user's session. Unlocking needs
+    // the password again, which the frozen session can't ask for, so bring up the greeter. Logging in there unlocks
+    // the home directory and then unlocks and activates the existing session.
+    for (const auto &[seatName, seat] : m_systemSeats.asKeyValueRange()) {
+        auto session = m_systemSessions.value(seat->activeSession(), nullptr);
+        if (!session || session->isGreeter() || !m_graphicalSeats.contains(seatName)) {
+            continue;
+        }
+
+        auto msg =
+            QDBusMessage::createMethodCall(u"org.freedesktop.home1"_s, u"/org/freedesktop/home1"_s, u"org.freedesktop.home1.Manager"_s, u"GetHomeByName"_s);
+        msg << session->userName();
+        QDBusPendingReply<uint, QString> reply = QDBusConnection::systemBus().asyncCall(msg);
+        auto watcher = new QDBusPendingCallWatcher(reply, this);
+        connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, reply, watcher, seatName]() {
+            watcher->deleteLater();
+            // Not a homed user, or homed isn't running.
+            if (!reply.isValid()) {
+                return;
+            }
+            if (reply.argumentAt<1>() == "locked"_L1) {
+                qInfo() << "Home directory of the active user on seat" << seatName << "is locked after resume, switching to greeter";
+                switchToGreeter(seatName);
+            }
+        });
+    }
+}
+
 void SeatManager::logindSeatAdded(const QString &name, const QDBusObjectPath &objectPath)
 {
     auto logindSeat = std::make_shared<LogindSeat>(name, objectPath);
diff --git a/src/daemon/SeatManager.h b/src/daemon/SeatManager.h
index 48540bdc..ac3c6671 100644
--- a/src/daemon/SeatManager.h
+++ b/src/daemon/SeatManager.h
@@ -50,6 +50,7 @@ Q_SIGNALS:

 private Q_SLOTS:
     void logindSecureAttentionKey(const QString &name, const QDBusObjectPath &objectPath);
+    void logindPrepareForSleep(bool start);
     void logindSeatAdded(const QString &name, const QDBusObjectPath &objectPath);
     void logindSeatRemoved(const QString &name, const QDBusObjectPath &objectPath);
     void logindSessionAdded(const QString &id, const QDBusObjectPath &objectPath);
